<script setup lang="ts">
definePageMeta({ title: 'Places' });
useSeoMeta({ title: 'Places' });
interface Place { name: string; category: string; area?: string; description?: string; address: string; lat?: number; lon?: number; img?: string; previewImage?:string; mrt?: {name:string;dist:number}; mrtOptions?: {name:string;entrance:string;access:string}[]; bus?:{code:string;name:string;dist?:number;access?:string}; transportStations?:string[]; transportSources?:string[]; officialUrl?:string; datasetUrl?:string; note?:string; checkedAt?:string; gate?:string; distance?:number; closed?:boolean; transportPending?:boolean; walkRoute?:{url:string;meters:number;minutes:number;endpoint:string;steps:string[];warnings:string[];kind:string}; }
const { data: attractions } = await useLazyFetch<{items:Place[]}>('/attractions.json', {server:false});
const { data: additions } = await useLazyFetch<{items:Place[];coverage?:{parkDestinations:number;excludedConnectorTrails:number;libraries:number;closedLibraries:number;parkTransportPending:number}}>('/explore-places.json', {server:false});
const { data: rail } = await useLazyFetch<{lines:{code:string;color:string;stations:{name:string;lat:number;lon:number}[]}[]}>('/mrt-lines.json', {server:false});
interface WalkFile { ids:string[]; links:Record<string,number[]>; unsnapped:string[]; }
const { data: walks } = await useLazyFetch<WalkFile>('/walk-links.json', {server:false});
const { data: stops } = await useLazyFetch<{features:{properties:{code:string}}[]}>('/bus-stops.json', {server:false});
// Match the current planner's reviewed approach and explicit hold gates by stable venue ID.
const heldVenueIds=new Set<string>(["p:Brooks Park", "p:Bulim Park", "p:Changi Beach Park", "p:Changi Boardwalk", "p:Faber Heights Park", "p:Greenwood Crescent Playground", "p:Holland Green Linear Park", "p:Holland Green Playground", "p:Lilac Drive Playground", "p:Mimosa Walk Playground", "p:Neram Crescent Playground", "p:Nim Crescent Open Space", "p:Orchid Village Playground", "p:Saraca Road Playground", "p:Seletar Terrace Park", "p:Springleaf Avenue Playground", "a:Bird Paradise", "a:Jewel Changi Airport", "p:Harbourfront Library"]);
const {data:reviewedAccess}=await useLazyFetch<{items:{id:string;lat:number;lon:number;buildingApproachReviewed:boolean;accessScope:string;links:{id:string;pathReviewed:boolean;source:string;meters:number;geometryFormat:string;geometry:[number,number][]}[] }[]}>('/venue-access.json',{server:false});
const inSingapore=(p:{lat:number;lon:number})=>Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&p.lat>=1.15&&p.lat<=1.5&&p.lon>=103.58&&p.lon<=104.1;
const commuteIds=computed(()=>{
 const w=walks.value;if(!w||!stops.value||!rail.value||!attractions.value||!additions.value||!reviewedAccess.value)return new Set<string>();
 const unsnapped=new Set(w.unsnapped);const index=new Map(w.ids.map((id,i)=>[id,i]));
 const valid=new Set([...stops.value.features.map(s=>`b:${s.properties.code}`),...rail.value.lines.flatMap(l=>l.stations.filter(s=>typeof s.lat==='number').map(s=>`m:${s.name}`))]);
 const ids=new Set<string>();
 for(const r of reviewedAccess.value.items){if(heldVenueIds.has(r.id)||!r.buildingApproachReviewed||!['building-approach','park-approach'].includes(r.accessScope)||!inSingapore(r))continue;
 if(r.links.some(l=>l.pathReviewed&&l.source==='OneMap'&&valid.has(l.id)&&Number.isFinite(l.meters)&&l.meters>0&&l.meters<=2000&&l.geometryFormat==='lat-lon'&&l.geometry?.length>1&&l.geometry.every(p=>inSingapore({lat:p[0],lon:p[1]}))))ids.add(r.id);}
 for(const [items,prefix] of [[attractions.value.items,'a'],[additions.value.items,'p']] as const){for(const p of items){const id=`${prefix}:${p.name}`;if(p.closed||heldVenueIds.has(id)||typeof p.lat!=='number'||typeof p.lon!=='number'||unsnapped.has(id))continue;const i=index.get(id);if(i===undefined)continue;const links=w.links[String(i)]??[];if(links.some((target,k)=>k%2===0&&valid.has(w.ids[target]??'')))ids.add(id);}}
 return ids;
});
function venueId(p:Place){return `${p.category==='Attractions'?'a':'p'}:${p.name}`;}
function canCommute(p:Place){return !p.closed&&commuteIds.value.has(venueId(p));}
const query=ref(''); const suggestionsOpen=ref(false); const activeSuggestion=ref(-1); const category=ref('All'); const expanded=ref<string|null>(null); const limit=ref(12);
// Official discovery links only: no copied or cached event listings.
function eventsLink(p:Place){
if(p.closed)return null;
if(p.category==='Libraries')return {url:'https://nlb.libcal.com/calendar/public',label:'Library programmes',note:'NLB calendar. Select this library on the official site.'};
if(p.name==='Singapore Botanic Gardens')return {url:'https://sbg.nparks.gov.sg/events/concerts/',label:'Concerts in the Gardens',note:'Official concert overview. Check NParks for event dates.'};
if(p.name.toLowerCase().includes('esplanade'))return {url:'https://www.esplanade.com/whats-on',label:"Esplanade What's On",note:'Official performances and registration.'};
if(p.category==='Parks')return {url:'https://www.nparks.gov.sg/visit/events',label:'Park activities',note:'NParks calendar. Check the event venue on the official site.'};
return null;
}
function fmt(m:number){return m<1000?`${Math.round(m/10)*10} m`:`${(m/1000).toFixed(1)} km`;}
const places=computed(()=>[...(additions.value?.items??[]),...(attractions.value?.items??[]).map(p=>({...p,category:'Attractions'}))]);
const suggestions=computed(()=>{const q=query.value.toLowerCase().trim();if(!q)return [];return places.value.filter(p=>(category.value==='All'||p.category===category.value)&&`${p.name} ${p.address} ${p.area??''} ${p.category}`.toLowerCase().includes(q)).slice(0,6);});
function chooseSuggestion(p:Place){query.value=p.name;suggestionsOpen.value=false;activeSuggestion.value=-1;}
function searchKeys(e:KeyboardEvent){if(e.key==='Escape'){suggestionsOpen.value=false;return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();suggestionsOpen.value=true;const n=suggestions.value.length;if(n)activeSuggestion.value=(activeSuggestion.value+(e.key==='ArrowDown'?1:-1)+n)%n;}if(e.key==='Enter'&&suggestionsOpen.value&&activeSuggestion.value>=0){e.preventDefault();const p=suggestions.value[activeSuggestion.value];if(p)chooseSuggestion(p);}}
function blurSearch(){setTimeout(()=>{suggestionsOpen.value=false;},150);}
// What's near me: one-shot fix, kept in memory on this device only. Distances are worked out in the browser; coordinates are never sent or saved.
const here=ref<{lat:number;lon:number}|null>(null); const nearBusy=ref(false); const nearMsg=ref('');
async function findNearMe(){
if(nearBusy.value)return; nearMsg.value='';
if(!navigator.geolocation){nearMsg.value='Location is not supported in this browser. Browse or search the list instead.';return;}
nearBusy.value=true;
try{
const fix=await new Promise<GeolocationPosition>((resolve,reject)=>{navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:10000,maximumAge:60000});});
if(Date.now()-fix.timestamp>120000||fix.coords.accuracy>1000){nearMsg.value='Your location is too old or imprecise. Try again, or browse the list.';return;}
const c={lat:fix.coords.latitude,lon:fix.coords.longitude};
if(!Number.isFinite(c.lat)||!Number.isFinite(c.lon)||!isInSingapore(c)){nearMsg.value='You seem to be outside Singapore, so nearby places are not shown. Browse the list instead.';return;}
here.value=c;limit.value=12;expanded.value=null;
}catch(e){const code=(e as {code?:number}).code;nearMsg.value=code===1?'Location permission was declined. Allow location in your browser settings, or browse the list.':'Could not get your location. Try again, or browse the list.';}
finally{nearBusy.value=false;}
}
function clearNear(){here.value=null;nearMsg.value='';limit.value=12;expanded.value=null;}
const matches=computed(()=>places.value.filter(p=>(category.value==='All'||p.category===category.value)&&`${p.name} ${p.address} ${p.area??''} ${p.category}`.toLowerCase().includes(query.value.toLowerCase().trim())));
const unranked=computed(()=>here.value?matches.value.filter(p=>p.closed||typeof p.lat!=='number'||typeof p.lon!=='number').length:0);
const filtered=computed(()=>{const h=here.value;if(!h)return matches.value.map(p=>({...p,distance:undefined}));
return matches.value.filter(p=>!p.closed&&typeof p.lat==='number'&&typeof p.lon==='number').map(p=>({...p,distance:haversineM(h,{lat:p.lat as number,lon:p.lon as number})})).sort((a,b)=>a.distance-b.distance);});
watch([query,category],()=>{limit.value=12;expanded.value=null;});
function lineChips(name:string){return rail.value?.lines.filter(l=>l.stations.some(s=>s.name===name))??[];}
function mrtOptions(p:Place){return p.mrtOptions??(p.transportStations??(p.mrt?[p.mrt.name]:[])).map(name=>({name,entrance:'',access:p.category==='Attractions'?'': 'Official station option; onward travel may be needed. Check the official visit information.'}));}
</script>
<template>
<div class="bg"><main class="pg">
<div class="heading-row"><h1>Places</h1><button type="button" class="go near-btn" :disabled="nearBusy" @click="findNearMe">{{nearBusy?'Finding...':here?'Refresh near me':"What's near me"}}</button></div><p class="intro">Places to enjoy, nearby or across Singapore.</p>
<div class="controls"><div class="search-wrap"><input v-model="query" type="search" placeholder="Search places" aria-label="Search places" role="combobox" aria-autocomplete="list" aria-controls="place-suggestions" :aria-expanded="suggestionsOpen && suggestions.length>0" :aria-activedescendant="activeSuggestion>=0 ? `suggestion-${activeSuggestion}` : undefined" @input="suggestionsOpen=true;activeSuggestion=-1" @focus="suggestionsOpen=true" @blur="blurSearch" @keydown="searchKeys"/><ul v-if="suggestionsOpen && suggestions.length" id="place-suggestions" class="suggestions" role="listbox" aria-label="Matching places"><li v-for="(p,i) in suggestions" :id="`suggestion-${i}`" :key="p.name" role="option" :aria-selected="activeSuggestion===i" @mousedown.prevent="chooseSuggestion(p)" @touchend.prevent="chooseSuggestion(p)" @click="chooseSuggestion(p)"><span>{{p.name}}</span><small>{{p.category}}</small></li></ul></div><div v-if="here" class="near-row"><button type="button" class="clear-near" @click="clearNear">Show all</button></div><p class="status" role="status" aria-live="polite">{{nearMsg||(here?'Nearest first, in a straight line, not walking time. Closed places and places without a mapped point are left out.':'Tap to list parks, libraries and attractions closest to you. Your location stays on your device and is not saved.')}}</p><div class="control-row"><select v-model="category" aria-label="Category"><option>All</option><option>Attractions</option><option>Libraries</option><option>Parks</option></select></div></div>

<p class="preview-note">Original concept illustrations, not photographs or views of the named sites. Check official visit information for current access.</p>
<details v-if="additions?.coverage" class="coverage"><summary>{{additions.coverage.parkDestinations}} park destinations · {{additions.coverage.libraries}} libraries · Coverage and gaps</summary><p>Official-directory coverage: {{additions.coverage.parkDestinations}} NParks destinations (including gardens, playgrounds and open spaces) and {{additions.coverage.libraries}} libraries. {{additions.coverage.excludedConnectorTrails}} connector/trail-only listings excluded. {{additions.coverage.closedLibraries}} libraries are temporarily closed. {{additions.coverage.parkTransportPending}} park entries still need entrance-level transport checks. This is not a list of every municipal/private park or school/university library.</p></details>
<p class="count">{{filtered.length}} places<template v-if="here">, nearest first<template v-if="unranked"> · {{unranked}} not ranked</template></template></p>
<div class="places"><article v-for="p in filtered.slice(0,limit)" :key="p.name" class="place"><div class="place-top"><figure class="thumb"><img :src="p.previewImage ?? `/img/attractions/${p.img}-320.webp`" :alt="`Illustration for ${p.name}, not an entrance photo`" width="320" height="180"/></figure><div class="card-copy"><span class="meta">{{p.category}}{{p.area?' · '+p.area:''}}<template v-if="p.distance!==undefined"> · <strong class="distance">{{fmt(p.distance)}} away</strong></template></span><h2>{{p.name}}</h2><p v-if="p.closed" class="closure">Temporarily closed</p><p v-if="p.transportPending" class="status">Transport check pending</p><p class="description">{{p.description??p.address}}</p></div><button class="go" :aria-expanded="expanded===p.name" @click="expanded=expanded===p.name?null:p.name">{{expanded===p.name?'Close':p.closed?'Details':'More'}}</button></div>
<div v-if="expanded===p.name" class="details"><img v-if="p.img || p.previewImage" :src="p.previewImage ?? `/img/attractions/${p.img}-640.webp`" :alt="`Illustration of ${p.name}`" width="640" height="360"/><p>{{p.address}}</p><p v-if="p.note">{{p.note}}</p><div v-for="m in (p.closed ? [] : mrtOptions(p))" :key="m.name" class="transport"><div><span v-for="line in lineChips(m.name)" :key="line.code" class="chip" :style="{background:line.color}">{{line.code}}</span><strong>{{m.name}}</strong><p>{{m.entrance}} {{m.access}}</p></div><span class="travel-actions"><NuxtLink v-if="canCommute(p)" :to="`/all?toId=${encodeURIComponent(venueId(p))}`" class="go">Commute</NuxtLink><span v-else class="commute-unavailable" role="status">{{walks && stops && reviewedAccess ? "Commute unavailable" : "Checking commute..."}}</span><NuxtLink :to="`/mrt?to=${encodeURIComponent(m.name)}`" class="go">By MRT</NuxtLink></span></div><div v-if="!p.closed && !mrtOptions(p).length" class="transport"><span>Journey planner</span><NuxtLink v-if="canCommute(p)" :to="`/all?toId=${encodeURIComponent(venueId(p))}`" class="go">Commute</NuxtLink><span v-else class="commute-unavailable" role="status">{{walks && stops && reviewedAccess ? "Commute unavailable" : "Checking commute..."}}</span></div><div v-if="p.bus && !p.closed" class="transport"><div><strong>{{p.bus.name}}</strong><p>Stop {{p.bus.code}}<template v-if="p.bus.dist!==undefined"> · {{fmt(p.bus.dist)}} from listed point, not walking distance</template><template v-if="p.bus.access"> · {{p.bus.access}}</template></p></div><NuxtLink :to="`/bus?stop=${p.bus.code}`" class="go">Bus arrivals</NuxtLink></div><details v-if="p.walkRoute && !p.closed" class="walk-route"><summary>{{p.walkRoute.kind}} · {{p.walkRoute.meters}} m · about {{p.walkRoute.minutes}} min</summary><p>Map-estimated route to {{p.walkRoute.endpoint}}, not a verified entrance or step-free route.</p><ol><li v-for="(step,i) in p.walkRoute.steps" :key="i">{{step}}</li></ol><a :href="p.walkRoute.url" target="_blank" rel="noopener noreferrer">Walking directions</a><p v-if="p.walkRoute.warnings.length" class="status">{{p.walkRoute.warnings.join(" ")}}</p></details><p v-if="!p.closed && !p.bus && p.category!=='Attractions'" class="status">Bus-stop access is not verified for this listing. Check official visit information.</p><p v-if="p.officialUrl"><a :href="p.officialUrl" target="_blank" rel="noopener noreferrer">Official visit information</a> · Checked {{p.checkedAt}}</p><p v-if="p.transportSources?.length" class="status">Transport checked {{p.checkedAt}} · <a v-for="(url,i) in p.transportSources" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{i ? " / " : ""}}Source {{i+1}}</a></p><p v-if="eventsLink(p)" class="event-link"><a :href="eventsLink(p)!.url" target="_blank" rel="noopener noreferrer">{{eventsLink(p)!.label}} ↗</a><span>{{eventsLink(p)!.note}}</span></p><p v-if="p.datasetUrl" class="status"><a :href="p.datasetUrl" target="_blank" rel="noopener noreferrer">Location dataset</a> · indicative point, not a verified entrance</p></div></article></div>
<p v-if="!filtered.length" role="status">{{here?'Nothing nearby matches. Try another category or tap Show all.':'No matches. Try another category or search.'}}</p><button v-if="filtered.length>limit" class="more" @click="limit+=12">Show more</button>
<p class="source">Park and library information checked against official NParks and NLB visit pages on 1 October 2026. Individual source links are in the place details. Illustrations are original concept art, not agency photos or verified entrance images.</p><DataCredits/>
</main></div>
</template>
<style scoped>
.bg{height:100%;width:100%;background:var(--md-sys-color-surface-container)}.pg{height:100%;box-sizing:border-box;overflow:auto;padding:24px;background:var(--md-sys-color-surface);border-radius:32px;color:var(--md-sys-color-on-surface)}h1{margin:0;font-size:30px;font-weight:500}.intro{margin:8px 0 20px;font-size:15px}.controls{max-width:720px}.controls input,.controls select{font:inherit;color:inherit;background:var(--md-sys-color-surface-container-lowest);border:1px solid var(--md-sys-color-outline-variant);border-radius:12px;min-height:46px;padding:10px 12px;box-sizing:border-box;width:100%;min-width:0}.control-row{display:grid;grid-template-columns:1fr;gap:8px;margin-top:8px}.search-wrap{position:relative}.suggestions{position:absolute;z-index:5;top:100%;left:0;right:0;list-style:none;margin:4px 0 0;padding:5px;background:var(--md-sys-color-surface-container-lowest);border:1px solid var(--md-sys-color-outline-variant);border-radius:12px;box-shadow:0 5px 16px #0002}.suggestions li{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:12px 9px;border-radius:7px;cursor:pointer;font-size:14px}.suggestions li:hover,.suggestions li[aria-selected=true]{background:var(--md-sys-color-surface-container)}.suggestions small{font-size:11px;color:var(--md-sys-color-on-surface-variant)}.preview-note{font-size:12px;color:var(--md-sys-color-on-surface-variant);margin:12px 0}.count{font-size:12px;margin:16px 0 10px;color:var(--md-sys-color-on-surface-variant)}.places{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-items:start}.place{border:1px solid var(--md-sys-color-outline-variant);border-radius:18px;background:var(--md-sys-color-surface-container-lowest);padding:16px}.place-top{display:grid;grid-template-columns:88px minmax(0,1fr);gap:8px 12px;align-items:start}.thumb{margin:0;grid-row:1 / span 2}.thumb img{display:block;width:88px;height:58px;object-fit:cover;border-radius:9px}.walk-route{padding:12px 0;border-top:1px solid var(--md-sys-color-outline-variant)}.walk-route summary{cursor:pointer;font-weight:600}.walk-route li{margin:7px 0}.coverage{font-size:12px;line-height:1.5;margin:12px 0;color:var(--md-sys-color-on-surface-variant)}.coverage summary{cursor:pointer}.coverage p{margin:8px 0}.closure{font-size:12px;font-weight:650;color:var(--sg-brand-text);margin:5px 0}.card-copy{min-width:0}.place-top>.go{grid-column:2;justify-self:end}.place-top h2{margin-top:3px}.meta,.distance{font-size:12px;color:var(--md-sys-color-on-surface-variant)}h2{font-size:17px;margin:5px 0;font-weight:650}.description{font-size:13px;line-height:1.45;margin:0}.go,.more{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;min-height:44px;box-sizing:border-box;background:var(--sg-brand-strong);color:#fff;border:0;border-radius:10px;padding:10px 12px;font:inherit;font-size:13px;font-weight:600;text-decoration:none;cursor:pointer}.details{border-top:1px solid var(--md-sys-color-outline-variant);margin-top:14px;padding-top:14px;font-size:13px;line-height:1.5}.details img{width:100%;height:auto;border-radius:12px}.transport{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--md-sys-color-outline-variant);padding:10px 0}.transport p{margin:4px 0}.status,.source{font-size:12px;line-height:1.5;color:var(--md-sys-color-on-surface-variant)}.chip{display:inline-block;padding:2px 5px;border-radius:5px;color:#fff;font-size:11px;margin-right:5px;font-weight:700}.gate{padding:10px;background:var(--md-sys-color-surface-container);border-radius:8px}.more{display:flex;margin:18px auto}.source{margin:22px 0}a{color:var(--sg-brand-text)}.go{color:#fff}:is(button,input,select,a):focus-visible{outline:3px solid var(--sg-brand-text);outline-offset:3px}@media(min-width:768px){.place-top{grid-template-columns:88px minmax(0,1fr) auto;align-items:center}.thumb{grid-row:1}.place-top>.go{grid-column:3;align-self:center}}@media(max-width:767px){.pg{padding:18px 14px;border-radius:0}.places{grid-template-columns:1fr}.place{padding:14px}.intro{margin-bottom:16px}.search-wrap{position:relative}.suggestions{position:absolute;z-index:5;top:100%;left:0;right:0;list-style:none;margin:4px 0 0;padding:5px;background:var(--md-sys-color-surface-container-lowest);border:1px solid var(--md-sys-color-outline-variant);border-radius:12px;box-shadow:0 5px 16px #0002}.suggestions li{display:flex;justify-content:space-between;gap:8px;align-items:center;padding:12px 9px;border-radius:7px;cursor:pointer;font-size:14px}.suggestions li:hover,.suggestions li[aria-selected=true]{background:var(--md-sys-color-surface-container)}.suggestions small{font-size:11px;color:var(--md-sys-color-on-surface-variant)}.preview-note{line-height:1.5}}
.heading-row{display:flex;align-items:center;justify-content:space-between;gap:12px;max-width:720px}.heading-row h1{flex-shrink:0}.heading-row .near-btn{white-space:nowrap}.near-row{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:10px}.clear-near{background:none;border:0;color:var(--sg-brand-text);font:inherit;font-size:13px;font-weight:600;min-height:44px;padding:0 6px;cursor:pointer;text-decoration:underline}.near-btn:disabled{opacity:.6;cursor:progress}.distance strong,strong.distance{color:var(--sg-brand-text)}
.event-link{display:flex;flex-direction:column;gap:3px}.event-link a{font-weight:600;align-self:flex-end;padding:8px 0}.event-link span{font-size:12px;color:var(--md-sys-color-on-surface-variant)}
.commute-unavailable{align-self:center;font-size:12px;color:var(--md-sys-color-on-surface-variant);max-width:95px;text-align:right}.travel-actions{display:flex;justify-content:flex-end;gap:8px;flex-shrink:0}.transport:has(.travel-actions){flex-wrap:wrap}.transport .travel-actions{margin-left:auto}
</style>
